# Pul: haftalik takroriy daromad/xarajat, Daromad rejasi, dollar maqsadi. Soat: 2026-11-09 (dushanba) 10:00.
import sys, os
sys.path.insert(0, os.environ.get('KT_ROOT', os.path.dirname(os.path.dirname(os.path.abspath(__file__)))) + '/tests')
from _pw import Run
with Run('pul_haftalik', when=(2026, 11, 9, 10, 0, 0)) as R:
    ev, chk, pg = R.ev, R.chk, R.pg
    pg.clock.set_system_time('2026-11-09T10:00:00')
    def fresh():
        ev("""()=>{window.confirm=()=>true;window.__t=[];window.toast=m=>window.__t.push(m);S.money=[];S.debts=[];S.fin={open:{p:{cash:0,card:0},d:{cash:0,card:0}},budget:0,sg:[],cb:{},rc:[],wl:[]};W='p';PV='r';K='out';tab='p';render()}"""); pg.wait_for_timeout(100)
    text = lambda: pg.inner_text('#app').replace('\xa0', ' ')
    fresh()
    chk('Reja shows the "Daromad rejasi" card with the sample button and the dollar goal block', 'Daromad rejasi' in text() and 'Namuna' in text() and 'Dollar maqsadi' in text())
    # qo'lda qoida qo'shish (formadan)
    pg.fill('#drja', '70 000'); pg.fill('#drjn', 'Dadam'); pg.click('#app button >> text="Du–Ju"'); pg.click('#app details button >> text="Qo‘shish"'); pg.wait_for_timeout(150)
    r = ev("S.fin.wr")
    chk('a rule was added from the form: income 70 000, Du–Ju (days 0-4), note "Dadam"', len(r) == 1 and r[0]['a'] == 70000 and r[0]['days'] == [0, 1, 2, 3, 4] and r[0]['k'] == 'in' and r[0]['n'] == 'Dadam', r)
    chk('it starts today (no backfill into the past): from = 2026-11-09', r[0]['from'] == '2026-11-09')
    ev("()=>{S.fin.wr[0].from='2026-11-02';S.fin.wr[0].last='';S.fin.wrd='';render()}"); pg.wait_for_timeout(150)
    m = ev("S.money.filter(x=>x.wr)")
    chk('with from = Monday 2 Nov, by Monday 9 Nov there are 6 records (Mon-Fri + today Mon), none on Saturday/Sunday', len(m) == 6 and sorted(x['d'] for x in m) == ['2026-11-02', '2026-11-03', '2026-11-04', '2026-11-05', '2026-11-06', '2026-11-09'], sorted(x['d'] for x in m))
    chk('their total is 6 × 70 000 = 420 000 and the balance matches', sum(x['a'] for x in m) == 420000 and ev("bal('p').tot") == 420000)
    chk('every record keeps the rule id, account, the income category and the note', all(x['k'] == 'in' and x['ac'] == 'cash' and x['n'] == 'Dadam' and x['w'] == 'p' for x in m))
    ids1 = sorted(x['id'] for x in m)
    ev("()=>{S.fin.wr[0].last='';S.fin.wrd='';render()}"); pg.wait_for_timeout(120)
    chk('running again (even after resetting the rule) does NOT create duplicates: still 6 records, same ids', ev("S.money.filter(x=>x.wr).length") == 6 and sorted(x['id'] for x in ev("S.money.filter(x=>x.wr)")) == ids1)
    # ikki qurilma: boshqa nusxada bir xil id
    ev("()=>{const a=S.money.filter(x=>x.wr).map(x=>x.id);S.money=[];S.fin.wr[0].last='';S.fin.wrd='';render();window.__b=S.money.filter(x=>x.wr).map(x=>x.id)}")
    chk('two devices generating the same days get identical ids (so the sync merge cannot duplicate them)', sorted(ev("window.__b")) == ids1)
    pg.clock.set_system_time('2026-11-10T10:00:00'); ev("()=>{S.fin.wrd='';render()}"); pg.wait_for_timeout(120)
    chk('the next day (Tuesday) adds exactly one more record', ev("S.money.filter(x=>x.wr).length") == 7)
    pg.clock.set_system_time('2026-11-14T10:00:00'); ev("()=>{S.fin.wrd='';render()}"); pg.wait_for_timeout(120)
    chk('Saturday adds nothing for a Mon–Fri rule (Wed, Thu, Fri added: total 10)', ev("S.money.filter(x=>x.wr).length") == 10)
    ev("()=>{drjTog(S.fin.wr[0].id)}"); pg.clock.set_system_time('2026-11-16T10:00:00'); ev("()=>{S.fin.wrd='';render()}"); pg.wait_for_timeout(120)
    chk('a paused rule creates nothing', ev("S.fin.wr[0].on") == 0 and ev("S.money.filter(x=>x.wr).length") == 10)
    ev("()=>{drjTog(S.fin.wr[0].id)}"); pg.wait_for_timeout(100)
    chk('resuming starts from today (no backfill of the paused days)', ev("S.fin.wr[0].on") == 1 and ev("S.fin.wr[0].from") == '2026-11-16')
    ev("()=>{drjDel(S.fin.wr[0].id)}"); pg.wait_for_timeout(100)
    chk('deleting a rule keeps the records already made', ev("S.fin.wr.length") == 0 and ev("S.money.filter(x=>x.wr).length") >= 10)
    # namuna va reja (foydalanuvchining haqiqiy raqamlari)
    pg.clock.set_system_time('2026-11-09T10:00:00'); fresh()
    pg.click('#app button >> text=Namuna'); pg.wait_for_timeout(150)
    chk('the sample adds 4 rules: Ishxona 75 000 (7 days), Dadam 70 000 (Mon–Fri), Ovqat 37 000, Yo‘lkira 27 000 (7 days)', ev("S.fin.wr.map(r=>[r.k,r.a,r.days.length].join('|'))") == ['in|75000|7', 'in|70000|5', 'out|37000|7', 'out|27000|7'], ev("S.fin.wr.map(r=>[r.k,r.a,r.days.length].join('|'))"))
    P = ev("drjPlan()")
    chk('plan: weekly income 875 000 (75 000×7 + 70 000×5), weekly spending 448 000, left 427 000', P['wi'] == 875000 and P['wo'] == 448000 and P['wn'] == 427000, P)
    chk('plan: monthly income ≈ 3 800 000 (875 000 / 7 × 30.4) and monthly spending ≈ 1 945 600', P['mi'] == 3800000 and P['mo'] == 1945600, P)
    t = text(); chk('the screen shows weekly 875 000, 448 000 and "Qoladigan pul" 427 000', '875 000' in t and '448 000' in t and '427 000' in t)
    # dollar maqsadi
    ev("()=>{drjSet('usd','1000');drjSet('rate','12 500')}"); pg.wait_for_timeout(100); P = ev("drjPlan()")
    chk('goal $1 000 × 12 500 = 12 500 000; 30% of 3 800 000 = 1 140 000 a month → 11 months', P['goal'] == 12500000 and P['pc'] == 30 and P['sv'] == 1140000 and P['eta'] == 11, P)
    chk('the screen says "~11 oyda yetasan"', '~11 oyda' in text())
    ev("drjSet('pc','20')"); pg.wait_for_timeout(80); P = ev("drjPlan()"); chk('20% → 760 000 a month → 17 months', P['sv'] == 760000 and P['eta'] == 17, P)
    ev("drjSet('pc','30')")
    ev("drjGoal()"); g = ev("S.fin.sg"); chk('"Jamg‘arma maqsadi qilib qo‘shish" creates one savings goal of 12 500 000 so‘m', len(g) == 1 and g[0]['a'] == 12500000 and g[0]['usd'] == 1000 and 'Maqsad: $1' in g[0]['t'], g)
    ev("()=>{drjSet('rate','13 000');drjGoal()}"); g = ev("S.fin.sg"); chk('changing the rate updates the SAME goal (13 000 000), no duplicate', len(g) == 1 and g[0]['a'] == 13000000, g)
    ev("()=>{S.fin.sg[0].s=2600000;render()}"); P = ev("drjPlan()"); chk('with 2 600 000 already saved: remaining 10 400 000, ETA ceil(10.4 / 1.14) = 10 months', P['rem'] == 10400000 and P['eta'] == 10, P)
    ev("()=>{S.fin.sg[0].s=13000000;render()}"); chk('when the goal is reached the card congratulates instead of counting months', 'yetgansan' in text())
    ev("()=>{drjSet('usd','');render()}"); chk('without $ and rate it asks for them', '$ va kursni yozsang' in text())
    # shaxsiy / dokon, uslublar
    ev("()=>{W='d';render()}"); chk('the shop wallet does not show the personal plan', 'Daromad rejasi' not in text()); ev("()=>{W='p';render()}")
    for cls, nm in (('', 'Klassik'), ('ui2', 'Yangi'), ('ui2 glass', 'Glass')):
        ev("(c)=>{document.documentElement.className=c;W='p';PV='r';render()}", cls); pg.wait_for_timeout(80)
        chk('%s style: no horizontal overflow on the plan screen' % nm, pg.evaluate("document.documentElement.scrollWidth<=window.innerWidth+1"))
    print('\n%d passed, %d failed' % (R.ok, R.bad))
